+///|
+let diagnostic_recording_health : DiagnosticRecordingHealth = {
+  dropped: 0,
+  first_dropped: 0,
+  last_dropped: 0,
+  reason: "",
+  phase: "",
+  os_errno: None,
+  warned: false,
+  incident: false,
+  incident_serial: 0,
+}
+
+///|
