+///|
+fn diagnostic_health_snapshot() -> Json {
+  if diagnostic_recording_health.incident ||
+    diagnostic_recording_health.dropped > 0 {
+    {
+      "status": "degraded",
+      "reason": diagnostic_recording_health.reason,
+      "phase": diagnostic_recording_health.phase,
+    }
+  } else {
+    { "status": "healthy" }
+  }
+}
+
+///|
+async fn publish_diagnostic_health() -> Unit {
+  guard @env.args() is [_, "--supervisor", ..] else { return }
+  @async.with_timeout(10, async fn() {
+    let directory = adapter_state_home()
+    let path = directory + "/diagnostic-health.json"
+    if !diagnostic_recording_health.incident &&
+      diagnostic_recording_health.dropped == 0 {
+      @fs.remove(path) catch {
+        _ => ()
+      }
+      return
+    }
+    let temporary = directory +
+      "/diagnostic-health." +
+      proxy_pid().to_string() +
+      ".tmp"
+    defer (@fs.remove(temporary) catch { _ => () })
+    @fs.write_file(
+      temporary,
+      diagnostic_health_snapshot().stringify(),
+      permission=0o600,
+    )
+    @fs.rename(temporary, path, replace=true)
+  }) catch {
+    _ => ()
+  }
+}
+
+///|
+async fn diagnostic_recording_warning(
+  reason : String,
+  phase~ : String = "",
+  os_errno? : Int32,
+) -> Unit {
+  let publish = !diagnostic_recording_health.incident ||
+    diagnostic_recording_health.reason != reason ||
+    diagnostic_recording_health.phase != phase
+  diagnostic_recording_health.incident = true
+  diagnostic_recording_health.incident_serial += 1
+  if diagnostic_recording_health.dropped == 0 {
+    diagnostic_recording_health.reason = reason
+    diagnostic_recording_health.phase = phase
+    diagnostic_recording_health.os_errno = os_errno
+  }
+  if publish {
+    publish_diagnostic_health()
+  }
+  if !diagnostic_recording_health.warned {
+    diagnostic_recording_health.warned = true
+    @async.with_timeout(10, async fn() {
+      @stdio.stderr.write(
+        "orca-env-devsy: warning: diagnostic recording is unavailable (" +
+        reason +
+        (if phase == "" { "" } else { ", phase=" + phase }) +
+        os_errno.map(code => ", errno=" + code.to_string()).unwrap_or("") +
+        ")\n",
+      )
+    }) catch {
+      _ => ()
+    }
+  }
+}
+
+///|
+async fn diagnostic_recording_failed(
+  reason : String,
+  phase~ : String = "",
+  os_errno? : Int32,
