+      let sink = @process.redirect_to_file("/dev/null", shared=true)
+      defer sink.close()
+      let child = @process.spawn(
+        group,
+        integration_binary(),
+        ["--supervisor", root],
+        extra_env=env,
+        stdout=sink,
+        stderr=sink,
+        no_wait=true,
+      )
+      idle_wait_for(async fn() { @fs.exists(root + "/supervisor.json") })
+      idle_wait_for(async fn() { @fs.exists(root + "/diagnostic-health.json") })
+      let health = @json.parse(
+        @fs.read_file(root + "/diagnostic-health.json").text(),
+      )
+      assert_eq(field(health, "status"), Some(Json::string("degraded")))
+      assert_eq(field(health, "reason"), Some(Json::string("lock_busy")))
+      let descriptor = @json.parse(
+        @fs.read_file(root + "/supervisor.json").text(),
+      )
+      assert_eq(
+        field(descriptor, "diagnosticHealthPath"),
+        Some(Json::string("diagnostic-health.json")),
+      )
+      let workspace = root + "/tunnels/health-test"
+      @fs.mkdir(workspace, recursive=true)
+      @fs.write_file(workspace + "/state.json", "{}")
+      let port = @string.parse_int(required(descriptor, "port"))
+      let socket = @socket.Tcp::connect(
+        @socket.Addr::parse("127.0.0.1:" + port.to_string()),
+      )
