+      ignore(read_registration(socket, 4096))
+      write_registration(socket, {
+        "directory": workspace,
+        "environment": { "ORCA_ENV_DEVSY_RECORDING": "1" },
+      })
+      let reply = read_registration(socket, 4096)
+      assert_eq(field(reply, "accepted"), Some(Json::boolean(true)))
+      assert_eq(
+        field(field(reply, "diagnosticHealth").unwrap(), "status"),
+        Some(Json::string("degraded")),
+      )
+      assert_false(@fs.exists(root + "/events.jsonl"))
