808	fn diagnostic_text(
809	  message : String,
810	  environment? : Map[String, String],
811	  omitted~ : Bool = false,
812	  protected_secrets? : Array[String],
813	  incomplete_final_line~ : Bool = false,
814	) -> String {
815	  let progress = Progress::new("diagnostic-error", environment?)
816	  if protected_secrets is Some(values) {
817	    for value in values {
818	      if value != "" {
819	        progress.secrets.push(value)
820	        for line in value.split("\n") {
821	          if line.trim() != "" && line.length() < value.length() {
822	            progress.secrets.push(line.to_owned())
823	          }
824	        }
825	      }
826	    }
827	  }
828	  progress.secrets.sort_by((a, b) => b.length().compare(a.length()))
829	  let lines = []
830	  let mut incomplete = omitted
831	  let source_lines = message.split("\n").to_array()
832	  for index in 0..<source_lines.length() {
833	    let line = source_lines[index]
834	    if lines.length() == 32 {
835	      incomplete = true
836	      ignore(lines.remove(1))
837	    }
838	    let truncated = line.length() > 1024
839	    let bounded = if truncated {
840	      incomplete = true
841	      line[:1024].to_owned()
842	    } else {
843	      line.to_owned()
844	    }
845	    let bounded = if truncated ||
846	      (incomplete_final_line && index == source_lines.length() - 1) {
847	      diagnostic_partial_secret(bounded, progress.secrets)
848	    } else {
849	      bounded
850	    }
851	    match progress.safe_message(bounded) {
852	      Some(safe) => lines.push(safe)
853	      None => {
854	        incomplete = true
855	        lines.push("[unavailable]")
856	      }
857	    }
858	  }
859	  if (incomplete || progress.details_truncated) &&
860	    lines.last() != Some("[error details incomplete or truncated]") {
861	    lines.push("[error details incomplete or truncated]")
862	  }
863	  lines.join("\n")
864	}
