1115	///|
1116	async fn DiagnosticCapture::read(
1117	  self : DiagnosticCapture,
1118	  reader : @process.ReadFromProcess,
1119	) -> Unit {
1120	  try {
1121	    while reader.read_some(max_len=4096) is Some(chunk) {
1122	      let remaining = self.limit - self.output.length()
1123	      let count = if chunk.length() < remaining {
1124	        chunk.length()
1125	      } else {
1126	        remaining
1127	      }
1128	      if count > 0 {
1129	        self.output.write_bytes(chunk[:count])
1130	      }
1131	      if count < chunk.length() {
1132	        self.truncated = true
1133	      }
1134	    }
1135	  } catch {
1136	    error =>
1137	      if @async.is_being_cancelled() {
1138	        raise error
1139	      } else {
1140	        self.truncated = true
1141	      }
1142	  }
1143	  self.finished = true
1144	}
