1146	///|
1147	async fn wait_diagnostic_captures(captures : Array[DiagnosticCapture]) -> Unit {
1148	  @async.with_timeout(250, async fn() {
1149	    while captures.iter().any(capture => !capture.finished) {
1150	      @async.sleep(5)
1151	    }
1152	  }) catch {
1153	    error => if @async.is_being_cancelled() { raise error }
1154	  }
1155	}
