278	async fn diagnostic_retained_records(file : @fs.File, size : Int64) -> String {
279	  let length = if size > 262144L { 262144 } else { size.to_int() }
280	  let bytes = FixedArray::make(length, b'\x00')
281	  let read = file.read_at(bytes, position=size - length.to_int64())
282	  let text = @utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()[:read])
283	  let lines = text.split("\n").to_array()
284	  let kept = FixedArray::make(lines.length(), false)
285	  let mut remaining = 65536
286	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
287	    if i == 0 && size > length.to_int64() {
288	      continue
289	    }
290	    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
291	    let overhead = if field(event, "runId") is Some(Json::String(_)) {
292	      100
293	    } else {
294	      0
295	    }
296	    let length = lines[i].length() + 1 + overhead
297	    if length <= remaining {
298	      kept[i] = true
299	      remaining -= length
300	    }
301	  }
302	  remaining = 65536
303	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
304	    if kept[i] || (i == 0 && size > length.to_int64()) {
305	      continue
306	    }
307	    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
308	    let failed = field(event, "errorType") is Some(_) ||
309	      (match field(event, "status") {
310	        Some(Json::String(status)) =>
311	          ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
312	            status,
313	          )
314	        _ => false
315	      })
316	    let overhead = if field(event, "runId") is Some(Json::String(_)) {
317	      100
318	    } else {
319	      0
320	    }
321	    let length = lines[i].length() + 1 + overhead
322	    if failed && length <= remaining {
323	      kept[i] = true
324	      remaining -= length
325	    }
326	  }
327	  let dropped_runs : Map[String, Bool] = Map([])
328	  for i in 0..<(lines.length() - 1) {
329	    if !kept[i] {
330	      let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
331	      if field(event, "runId") is Some(Json::String(id)) {
332	        dropped_runs.set(id, true)
333	      }
334	    }
335	  }
336	  let result = @buffer.Buffer(size_hint=131072)
337	  for i in 0..<lines.length() {
338	    if kept[i] {
339	      let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
340	      if field(event, "runId") is Some(Json::String(id)) {
341	        set_field(
342	          event,
343	          "runCompleteness",
344	          Json::string(
345	            if dropped_runs.contains(id) ||
346	              field(event, "runCompleteness") == Some(Json::string("partial")) {
347	              "partial"
348	            } else {
349	              "unknown"
350	            },
351	          ),
352	        )
353	        set_field(event, "runMissingReason", Json::string("retention_limit"))
354	        result.write_string_utf8(event.stringify() + "\n")
355	      } else {
356	        result.write_string_utf8(lines[i].to_owned() + "\n")
357	      }
358	    }
359	  }
360	  @utf8.decode_lossy(result.to_bytes())
361	}
