172	///|
173	fn terminal_text(text : String) -> String? {
174	  let output = @buffer.Buffer(size_hint=256)
175	  let mut state = 0
176	  for c in text.iter() {
177	    match state {
178	      0 =>
179	        if c == '\u001b' {
180	          state = 1
181	        } else if c.to_int() < 32 && c != '\t' {
182	          return None
183	        } else {
184	          output.write_char_utf8(c)
185	        }
186	      1 =>
187	        if c == '[' {
188	          state = 2
189	        } else if c == ']' {
190	          state = 3
191	        } else {
192	          return None
193	        }
194	      2 => if c >= '@' && c <= '~' { state = 0 }
195	      3 => if c == '\u0007' { state = 0 } else if c == '\u001b' { state = 4 }
196	      _ => if c == '\\' { state = 0 } else { state = 3 }
197	    }
198	  }
199	  if state != 0 {
200	    None
201	  } else {
202	    Some(@utf8.decode_lossy(output.to_bytes()))
203	  }
204	}
