472	///|
473	async fn Progress::stderr_line(
474	  self : Progress,
475	  line : String,
476	  statuses~ : Bool,
477	  messages~ : Bool,
478	) -> Unit {
479	  let event = @json.parse(line) catch { _ => Json::null() }
480	  if event != Json::null() {
481	    if event is Json::Object(_) &&
482	      field(event, "kind") == Some(Json::string("status")) &&
483	      (statuses || messages) {
484	      self.status(event)
485	    }
486	    let truncated : Ref[Bool] = { val: false, }
487	    let safe = diagnostic_json(event, {}, self.secrets, truncated, 0).stringify()
488	    if truncated.val {
489	      self.details_truncated = true
490	    }
491	    self.message(safe, debug=false, warning=true, emit=false)
492	    return
493	  } else if event == Json::null() &&
494	    (line.trim().has_prefix("[") || line.trim().has_prefix("{")) {
495	    self.message(line, debug=false, warning=true, emit=false)
496	    return
497	  }
498	  self.line(line, statuses~, messages~)
499	}
