501	///|
502	async fn Progress::read_output(
503	  self : Progress,
504	  reader : @process.ReadFromProcess,
505	  capture~ : Bool,
506	  statuses~ : Bool = false,
507	  messages~ : Bool = false,
508	  raw_messages~ : Bool = false,
509	) -> String {
510	  let output = @buffer.Buffer(size_hint=4096)
511	  let pending = @buffer.Buffer(size_hint=4096)
512	  let mut oversized = false
513	  let mut tail = ""
514	  while reader.read_some(max_len=4096) is Some(chunk) {
515	    if capture {
516	      output.write_bytes(chunk)
517	    } else {
518	      tail += @utf8.decode_lossy(chunk)
519	      if tail.length() > 8192 {
520	        tail = tail[tail.length() - 8192:].to_owned()
521	      }
522	    }
523	    for byte in chunk {
524	      if byte == b'\n' || byte == b'\r' {
525	        if !oversized && pending.length() > 0 {
526	          let line = @utf8.decode(pending.to_bytes()) catch {
527	            _ => {
528	              self.details_truncated = true
529	              ""
530	            }
531	          }
532	          if raw_messages {
533	            self.message(line, debug=false, warning=true, emit=false)
534	          } else if capture {
535	            self.line(line, statuses~, messages~)
536	          } else {
537	            self.stderr_line(line, statuses~, messages~)
538	          }
539	        }
540	        pending.reset()
541	        oversized = false
542	      } else if !oversized {
543	        if pending.length() == 65536 {
544	          pending.reset()
545	          oversized = true
546	          self.details_truncated = true
547	        } else {
548	          pending.write_byte(byte)
549	        }
550	      }
551	    }
552	  }
553	  if !oversized && pending.length() > 0 {
554	    let line = @utf8.decode(pending.to_bytes()) catch {
555	      _ => {
556	        self.details_truncated = true
557	        ""
558	      }
559	    }
560	    if raw_messages {
561	      self.message(line, debug=false, warning=true, emit=false)
562	    } else if capture {
563	      self.line(line, statuses~, messages~)
564	    } else {
565	      self.stderr_line(line, statuses~, messages~)
566	    }
567	  }
568	  if capture {
569	    @utf8.decode(output.to_bytes())
570	  } else {
571	    tail
572	  }
573	}

