 90	      if line.trim() != "" && line.length() < pairing.length() {
 91	        progress.secrets.push(line.to_owned())
 92	      }
 93	    }
 94	    progress.secrets.sort_by((a, b) => b.length().compare(a.length()))
 95	  }
 96	  let mut phase = "master"
 97	  let mut exit_code = None
 98	  let mut failure_codes : Array[Json] = []
 99	  errdefer save_diagnostic(
100	    "activity-probe",
101	    "failed",
102	    error_type="observation_failed",
103	    phase~,
104	    exit_code?,
105	    evidence={ "errors": Json::array(failure_codes) },
106	    error_message=progress.failure_detail(),
107	    details_truncated=progress.details_truncated,
108	    tunnel_directory=directory,
109	    recording=state_recording(state),
110	    environment=workspace_environment(state),
111	    protected_secrets=[pairing],
112	  )
113	  @async.with_timeout(30000, async fn() {
114	    let args = mux_ssh_args(state)
115	    phase = "spawn"
116	    @async.with_task_group(async fn(group) {
117	      let child = @process.spawn(
118	        group,
119	        workspace_program(state, "ssh"),
120	        extra_env=workspace_environment(state),
121	        inherit_env=false,
122	        cwd?=workspace_directory(state).map(path => path[:]),
123	        args + [script],
124	        stdin=input,
125	        stdout=reader,
126	        stderr~,
127	      )
128	      let collected_errors = group.spawn(async fn() {
129	        ignore(progress.read_output(errors, capture=false))
130	      })
131	      let reading = group.spawn(async fn() {
132	        let buffer = @buffer.Buffer()
133	        let bytes = FixedArray::make(4096, b'\x00')
134	        while true {
135	          let count = output.read(bytes)
136	          if count == 0 {
137	            break
138	          }
139	          guard buffer.length() + count <= 4194304 else {
140	            raise AdapterError("Activity response too large")
141	          }
142	          buffer.write_bytes(Bytes::from_array(bytes[:count].to_owned()))
143	        }
144	        @utf8.decode(buffer.to_bytes())
145	      })
146	      let payload : Json = { "pairingCode": pairing }
147	      writer.write(payload.stringify())
148	      writer.close()
149	      phase = "result"
150	      let code = child.wait()
151	      exit_code = Some(code)
152	      collected_errors.wait()
153	      phase = "schema"
154	      let raw = reading.wait()
155	      let parsed = Some(@json.parse(raw)) catch { _ => None }
156	      if parsed is Some(value) &&
157	        field(value, "errors") is Some(Json::Array(errors)) {
158	        failure_codes = errors.filter_map(error => {
159	          match field(error, "code") {
160	            Some(Json::String(code)) if code.length() > 0 &&
161	              code.length() <= 80 &&
162	              code.iter().all(c => (c >= 'a' && c <= 'z') || c == '_') =>
163	              Some(Json::string(code))
164	            _ => None
165	          }
166	        })
167	      }
168	      guard code == 0 else {
169	        raise AdapterError(
170	          "Remote activity probe failed (exit \{code}; errors " +
171	          Json::array(failure_codes).stringify() +
172	          ")",
173	        )
174	      }
175	      guard parsed is Some(value) else {
176	        raise AdapterError("Invalid activity JSON")
177	      }
178	      guard field(value, "schemaVersion") == Some(Json::number(1)) &&
179	        ["idle", "active", "unknown"].contains(required(value, "activity")) else {
180	        raise AdapterError("Invalid activity response")
181	      }
182	      value
183	    })
184	  })
185	}
