268	///|
269	async fn bulk_one(mode : String, state : Json, options : BulkOptions) -> Json? {
270	  let id = required(state, "workspaceId")
271	  let saved_secrets = saved_workspace_secrets(state)
272	  let secrets = saved_secrets.unwrap_or([])
273	  if saved_secrets is None {
274	    suppress_workspace_recording(state)
275	  }
276	  let result : Json = {
277	    "id": id,
278	    "uid": required(state, "workspaceUid"),
279	    "context": required(state, "context"),
280	    "provider": options.provider,
281	    "identityVerified": false,
282	    "vmStatus": "unknown",
283	    "activity": "unknown",
284	    "outcome": "skipped",
285	  }
286	  let mut mutating = false
287	  try {
288	    set_field(result, "autoStop", idle_status(state))
289	    let effective_context = bulk_context(state)
290	    guard required(state, "context") == effective_context else {
291	      save_diagnostic(
292	        "bulk-workspace",
293	        "excluded",
294	        evidence={
295	          "id": id,
296	          "savedContext": required(state, "context"),
297	          "effectiveContext": effective_context,
298	          "reason": "context_mismatch",
299	        },
300	        protected_secrets=secrets,
301	        environment=workspace_environment(state),
302	        recording=operation_recording(state),
303	      )
304	      return None
305	    }
306	    let lock = connection_operation_lock(state, validate=false)
307	    defer lock.close()
308	    snapshot_workspace_recording(state, required(state, "tunnelDirectory"))
309	    match saved_workspace_secrets(state) {
310	      Some(values) =>
311	        for secret in values {
312	          secrets.push(secret)
313	        }
314	      None => suppress_workspace_recording(state)
315	    }
316	    validate_connection_owner(state)
317	    let (in_scope, matched) = bulk_identity(state, options.provider)
318	    guard in_scope else { return None }
319	    set_field(result, "identityVerified", Json::boolean(matched))
320	    guard matched else {
321	      set_field(
322	        result,
323	        "evidence",
324	        unknown_activity("workspace_missing_or_replaced"),
325	      )
326	      save_diagnostic(
327	        "bulk-workspace",
328	        "skipped",
329	        error_type="workspace_missing_or_replaced",
330	        evidence=result,
331	        protected_secrets=secrets,
332	        environment=workspace_environment(state),
333	        recording=operation_recording(state),
334	      )
335	      return Some(result)
336	    }
337	    let status = workspace_status(state)
338	    set_field(result, "vmStatus", Json::string(status))
339	    let activity_pairing : Ref[String?] = { val: None, }
340	    let evidence = if status != "Running" {
341	      unknown_activity("workspace_not_running")
342	    } else if options.force || mode == "resume" {
343	      unknown_activity(
344	        if options.force {
345	          "forced_without_activity_check"
346	        } else {
347	          "resume_does_not_require_activity"
348	        },
349	      )
350	    } else {
351	      observe_activity(state, pairing_out=activity_pairing) catch {
352	        error =>
353	          unknown_activity(
354	            if activity_pairing.val is Some(_) {
355	              diagnostic_error(error, environment=workspace_environment(state))
356	            } else {
357	              workspace_error_detail(state, error)
358	            },
359	          )
360	      }
361	    }
362	    set_field(result, "activity", field(evidence, "activity").unwrap())
363	    let evidence_incomplete : Ref[Bool] = { val: false, }
364	    let safe_evidence = if status != "Running" ||
365	      options.force ||
366	      mode == "resume" {
367	      evidence
368	    } else {
369	      match
370	        saved_workspace_secrets(
371	          state,
372	          for_output=true,
373	          include_pairing=activity_pairing.val is None,
374	        ) {
375	        Some(values) => {
376	          if activity_pairing.val is Some(pairing) && pairing != "" {
377	            values.push(pairing)
378	            for line in pairing.split("\n") {
379	              if line.trim() != "" && line.length() < pairing.length() {
380	                values.push(line.to_owned())
381	              }
382	            }
383	          }
384	          diagnostic_json(
385	            evidence,
386	            workspace_environment(state),
387	            values,
388	            evidence_incomplete,
389	            0,
390	            stable_activity=true,
391	          )
392	        }
393	        None => {
394	          evidence_incomplete.val = true
395	          (
396	            {
397	              "activity": field(evidence, "activity").unwrap(),
398	              "reason": "activity details unavailable",
399	              "detailsTruncated": true,
400	            } : Json)
401	        }
402	      }
403	    }
404	    set_field(result, "evidence", safe_evidence)
405	    if evidence_incomplete.val {
406	      set_field(result, "evidenceTruncated", Json::boolean(true))
407	    }
408	    save_diagnostic(
409	      "bulk-observation",
410	      mode,
411	      tunnel_directory=required(state, "tunnelDirectory"),
412	      evidence=result,
413	      evidence_incomplete=evidence_incomplete.val,
414	      evidence_stable_activity=true,
415	      protected_secrets=secrets,
416	      environment=workspace_environment(state),
417	      recording=operation_recording(state),
418	    )
419	    if mode == "status" {
420	      set_field(result, "outcome", Json::string("observed"))
421	      save_diagnostic(
422	        "bulk-workspace",
423	        "observed",
424	        evidence=result,
425	        evidence_incomplete=evidence_incomplete.val,
426	        evidence_stable_activity=true,
427	        protected_secrets=secrets,
428	        environment=workspace_environment(state),
429	        recording=operation_recording(state),
430	      )
431	      return Some(result)
432	    }
433	    if mode == "stop" {
434	      if status == "Stopped" {
435	        set_field(result, "reason", Json::string("already_stopped"))
436	      } else if !options.force &&
437	        (
438	          status != "Running" ||
439	          field(evidence, "activity") != Some(Json::string("idle"))
440	        ) {
441	        set_field(result, "reason", Json::string("not_idle"))
442	      } else {
443	        let (scope, valid) = bulk_identity(state, options.provider)
444	        guard scope && valid else {
445	          raise AdapterError("Workspace changed before stop")
446	        }
447	        mutating = true
448	        pause_tunnel(state)
449	        defer unpause_tunnel(state)
450	        stop_workspace(state)
451	        set_field(result, "outcome", Json::string("success"))
452	      }
453	    } else if status == "Running" {
454	      set_field(result, "reason", Json::string("already_running"))
455	    } else if status != "Stopped" {
456	      set_field(result, "reason", Json::string("workspace_not_stopped"))
457	    } else {
458	      let (scope, valid) = bulk_identity(state, options.provider)
459	      guard scope && valid else {
460	        raise AdapterError("Workspace changed before resume")
461	      }
462	      mutating = true
463	      unpause_tunnel(state)
464	      ignore(
465	        devsy(
466	          state,
467	          [
468	            "--result-format", "json", "workspace", "up", "--id", id, "--ide-launch",
469	            "skip",
470	          ] +
471	          orca_storage_args(state),
472	          "workspace-resume",
473	        ),
474	      )
475	      set_field(result, "outcome", Json::string("success"))
476	      idle_reset(state, "workspace_resumed")
477	    }
478	  } catch {
479	    error => {
480	      set_field(
481	        result,
482	        "outcome",
483	        Json::string(if mutating { "failed" } else { "skipped" }),
484	      )
485	      let detail = workspace_error_detail(state, error)
486	      set_field(result, "evidence", unknown_activity(detail))
487	      set_field(result, "error", Json::string(detail))
488	    }
489	  }
490	  if mode == "resume" &&
491	    field(result, "outcome") == Some(Json::string("success")) {
492	    recover_connection(state) catch {
493	      error => {
494	        set_field(result, "outcome", Json::string("failed"))
495	        set_field(
496	          result,
497	          "error",
498	          Json::string(workspace_error_detail(state, error)),
499	        )
500	      }
501	    }
502	  }
503	  save_diagnostic(
504	    "bulk-workspace",
505	    mode,
506	    evidence=result,
507	    evidence_incomplete=field(result, "evidenceTruncated") ==
508	      Some(Json::boolean(true)),
509	    evidence_stable_activity=true,
510	    protected_secrets=secrets,
511	    environment=workspace_environment(state),
512	    recording=operation_recording(state),
513	  )
514	  Some(result)
515	}
