551	///|
552	async fn bulk_inner(
553	  mode : String,
554	  args : Array[String],
555	  recording_allowed : Ref[Bool],
556	) -> Int32 {
557	  let options = bulk_options(mode, args)
558	  save_diagnostic("bulk", "started", evidence={
559	    "action": mode,
560	    "provider": options.provider,
561	    "jobs": options.jobs,
562	    "force": options.force,
563	  })
564	  let base = adapter_state_home() + "/tunnels"
565	  let states : Array[Json] = []
566	  let discovery_errors : Array[Json] = []
567	  let discovery_secrets : Array[String] = []
568	  let mut discovery_recording = true
569	  if @fs.exists(base) {
570	    for name in @fs.readdir(base, sort=true) {
571	      let directory = base + "/" + name
572	      let mut discovery_phase = "kind"
573	      try {
574	        if @fs.kind(directory, follow_symlink=false) != @fs.FileKind::Directory ||
575	          !@fs.exists(directory + "/enabled") {
576	          continue
577	        }
578	        discovery_phase = "read"
579	        let raw = @fs.read_file(directory + "/state.json").text()
580	        discovery_phase = "parse"
581	        let state = @json.parse(raw)
582	        discovery_phase = "validate"
583	        validate_state(state)
584	        guard field(state, "devsyEnv") is Some(Json::Object(_)) else {
585	          raise AdapterError("Missing saved Devsy environment")
586	        }
587	        ignore(required(state, "workspaceUid"))
588	        ignore(required(state, "context"))
589	        set_field(state, "tunnelDirectory", Json::string(directory))
590	        set_field(state, "provider", Json::string(options.provider))
591	        snapshot_workspace_recording(state, directory)
592	        states.push(state)
593	      } catch {
594	        error => {
595	          discovery_errors.push({
596	            "savedState": directory,
597	            "reason": diagnostic_error(error),
598	          })
599	          let (allowed, secrets) = record_discovery_error(
600	            "bulk-discovery", directory, discovery_phase, error,
601	          )
602	          discovery_recording = discovery_recording && allowed
603	          for secret in secrets {
604	            discovery_secrets.push(secret)
605	          }
606	        }
607	      }
608	    }
609	  }
610	  recording_allowed.val = recording_allowed.val &&
611	    discovery_recording &&
612	    states.iter().all(workspace_recording)
613	  let keys : Map[String, Int32] = Map([])
614	  for state in states {
615	    let key = required(state, "context") + ":" + required(state, "workspaceUid")
616	    keys.set(key, keys.get(key).unwrap_or(0) + 1)
617	  }
618	  let results : Array[Json] = []
619	  let permits = @async.Semaphore(options.jobs)
620	  @async.with_task_group(async fn(group) {
621	    for state in states {
622	      let key = required(state, "context") +
623	        ":" +
624	        required(state, "workspaceUid")
625	      if keys.get(key) != Some(1) {
626	        discovery_errors.push({
627	          "savedState": required(state, "tunnelDirectory"),
628	          "reason": "duplicate_saved_identity",
629	        })
630	        record_selection_failure(
631	          "bulk-discovery", state, "identity", "duplicate_saved_identity", "Duplicate saved workspace identity",
632	        )
633	        continue
634	      }
635	      permits.acquire()
636	      group.spawn_bg(async fn() {
637	        defer permits.release()
638	        if bulk_one(mode, state, options) is Some(result) {
639	          results.push(result)
640	        }
641	      })
642	    }
643	  })
644	  results.sort_by((a, b) => {
645	    let a_id = match field(a, "id") {
646	      Some(Json::String(id)) => id
647	      _ => ""
648	    }
649	    let b_id = match field(b, "id") {
650	      Some(Json::String(id)) => id
651	      _ => ""
652	    }
653	    a_id.compare(b_id)
654	  })
655	  let failures = results
656	    .filter(r => field(r, "outcome") == Some(Json::string("failed")))
657	    .length()
658	  let output : Json = {
659	    "schemaVersion": 1,
660	    "action": mode,
661	    "provider": options.provider,
662	    "workspaces": results,
663	    "failed": failures,
664	    "discoveryErrors": discovery_errors,
665	  }
666	  @stdio.stdout.write(output.stringify(indent=2) + "\n")
667	  recording_allowed.val = recording_allowed.val &&
668	    states.iter().all(workspace_recording)
669	  let secrets : Array[String] = [] + discovery_secrets
670	  for state in states {
671	    match saved_workspace_secrets(state) {
672	      Some(values) =>
673	        for secret in values {
674	          secrets.push(secret)
675	        }
676	      None => {
677	        suppress_workspace_recording(state)
678	        recording_allowed.val = false
679	      }
680	    }
681	  }
682	  save_diagnostic(
683	    "bulk",
684	    if failures > 0 {
685	      "failed"
686	    } else if !discovery_errors.is_empty() {
687	      "partial"
688	    } else {
689	      "success"
690	    },
691	    error_type?=if !discovery_errors.is_empty() {
692	      Some("saved_state_invalid")
693	    } else {
694	      None
695	    },
696	    evidence=output,
697	    evidence_incomplete=results
698	      .iter()
699	      .any(result => {
700	        field(result, "evidenceTruncated") == Some(Json::boolean(true))
701	      }),
702	    evidence_stable_activity=true,
703	    protected_secrets=secrets,
704	    recording=recording_allowed.val,
705	  )
706	
707	  failures
708	}

