 34	async fn register_workspace(directory : String, environment? : Json) -> Unit {
 35	  let mut detail = "Supervisor registration endpoint is not ready"
 36	  @async.with_timeout(10000, async fn() {
 37	    while true {
 38	      try {
 39	        ensure_supervisor()
 40	        register_workspace_inner(directory, environment?)
 41	        return
 42	      } catch {
 43	        error => detail = diagnostic_error(error)
 44	      }
 45	      @async.sleep(100)
 46	    }
 47	  }) catch {
 48	    @async.TimeoutError =>
 49	      raise AdapterError("Workspace registration timed out: " + detail)
 50	    error => raise error
 51	  }
