230	          }
231	        } else if value < chars.length() && ['"', '\''].contains(chars[value]) {
232	          let quote = chars[value]
233	          buffer.write_char_utf8(quote)
234	          value += 1
235	          while value < chars.length() && chars[value] != quote {
236	            if chars[value] == '\\' && value + 1 < chars.length() {
237	              value += 1
238	            }
239	            value += 1
240	          }
241	          buffer.write_string_utf8("[redacted]")
242	          i = value
243	        } else {
