255	            value = value_end
256	            while value_end < chars.length() &&
257	                  !credential_end(chars[value_end]) {
258	              value_end += 1
259	            }
260	          }
261	          if value + 10 <= chars.length() &&
262	            character_text(chars, value, value + 10) == "[redacted]" {
263	            value_end = value + 10
264	          }
265	          if value_end > value {
266	            buffer.write_string_utf8("[redacted]")
267	          }
268	          i = value_end
269	        }
270	        continue
271	      }
272	      buffer.write_string_utf8(word)
273	      i = end
274	      continue
275	    }
276	    buffer.write_char_utf8(chars[i])
277	    i += 1
278	  }
279	  @utf8.decode_lossy(buffer.to_bytes())
280	}
